int main(){using namespace game_lab;OriginalMapTerrain t;t.activeSide=112;t.flags.assign(51984,0x80000);for(size_t y=58;y<170;++y)for(size_t x=58;x<170;++x)t.flags[y*228+x]=8;OriginalBuildingFootprint f;f.type=59;f.x=30;f.y=40;f.size=1;f.width=7;f.height=4;bool complete=true;for(unsigned scale:{1u,2u,4u}){OriginalMapCamera c;c.centerX=33;c.centerY=41.5;c.scale=scale;c=originalBuildingFocusCamera({f},c);auto v=renderOriginalBuildingFootprints(t,{f},c);complete&=v.visible==1&&v.outlinePixels==880*scale;std::cout<<"{\"scale\":"<<scale<<",\"width\":"<<c.width<<",\"height\":"<<c.height<<",\"valid\":"<<v.valid<<",\"visible\":"<<v.visible<<",\"pixels\":"<<v.outlinePixels<<",\"expected_unclipped\":"<<880*scale<<"}\n";}return complete?0:1;}
